#pragma once

#ifdef ENABLE_OOT3D_VULKAN

#include "fast/oot3d/effect_graph_pass_barriers.h"
#include "fast/oot3d/reflection_ibl.h"

#include <vulkan/vulkan.h>

#include <cstdint>
#include <memory>
#include <string>

namespace Fast::Oot3d {

class NriInteropContext;

// Owns a small, prefiltered environment cube and a split-sum GGX BRDF LUT.
// Both are generated by NRI compute from the low-frequency PICA environment
// profile and remain independent from the FidelityFX adapter.
class ReflectionIblPass final {
  public:
    static constexpr uint32_t EnvironmentSize = 32U;
    static constexpr uint32_t EnvironmentMipCount = 6U;
    static constexpr uint32_t BrdfSize = 64U;

    ReflectionIblPass();
    ~ReflectionIblPass();
    ReflectionIblPass(const ReflectionIblPass&) = delete;
    ReflectionIblPass& operator=(const ReflectionIblPass&) = delete;

    bool Initialize(VkPhysicalDevice physicalDevice, VkDevice device,
                    NriInteropContext& interop);
    bool Execute(uint32_t frameIndex,
                 const ReflectionEnvironmentProfile& profile);
    void InvalidateProfile();
    void Shutdown();

    [[nodiscard]] bool Available() const;
    [[nodiscard]] VkImage EnvironmentImage() const;
    [[nodiscard]] VkImage BrdfImage() const;
    [[nodiscard]] bool EnvironmentOwnedByNri() const;
    [[nodiscard]] bool BrdfOwnedByNri() const;
    [[nodiscard]] bool ComputeOwnedByNri() const;
    [[nodiscard]] bool BarriersOwnedByNri() const;
    [[nodiscard]] const EffectPassBarrierExecution& LastBarrierExecution()
        const;
    [[nodiscard]] bool ProfileUpdatedLastExecute() const;
    [[nodiscard]] bool PicaDerivedLastExecute() const;
    [[nodiscard]] const std::string& UnavailableReason() const;

  private:
    struct Impl;
    std::unique_ptr<Impl> mImpl;
};

} // namespace Fast::Oot3d

#endif
